const IDLE_SUBAGENTS_SQL: &str = r"SELECT s.id, COALESCE(MAX(e.created_at), s.created_at) AS last_activity
FROM sessions s LEFT JOIN events e ON e.session = s.id
WHERE s.root_session_id IS NOT NULL AND s.archived = 0
GROUP BY s.id
HAVING COALESCE(MAX(e.created_at), s.created_at) <= ?1
ORDER BY last_activity, s.id";

